('29', 'Goods (other than radioactive ores) answering to a description in heading 2844 or 2845 — classifiable only in those headings', ARRAY['28']::text[], '2844', 'Section VI Note 1(A)', '(A) Goods (other than radioactive ores) answering to a description in heading 2844 or 2845 are to be classified in those headings and in no other heading of this Schedule.'),
('29', 'Goods answering to a description in heading 2843, 2846 or 2852 — classifiable only in those headings within this Section', ARRAY['28']::text[], '2843', 'Section VI Note 1(B)', '(B) Subject to paragraph (A) above, goods answering to a description in heading 2843, 2846 or 2852 are to be classified in those headings and in no other heading of this Section.'),
('29', 'Goods classifiable in heading 3004, 3005, 3006, 3212, 3303, 3304, 3305, 3306, 3307, 3506, 3707 or 3808 by reason of being put up in measured doses or for retail sale', ARRAY['30','32','33','35','37','38']::text[], NULL, 'Section VI Note 2', 'Subject to Note 1 above, goods classifiable in heading 3004, 3005, 3006, 3212, 3303, 3304, 3305, 3306, 3307, 3506, 3707 or 3808 by reason of being put up in measured doses or for retail sale are to be classified in those headings and in no other heading of this Schedule.'),
('29', 'Products described by name or function in any Section VI heading also matching heading 3827 — classified by name/function, not under 3827', NULL, NULL, 'Section VI Note 4', 'Where a product answers to a description in one or more of the headings in Section VI by virtue of being described by name or function and also to heading 3827, then it is classifiable in a heading that references the product by name or function and not under heading 3827.'),
